tool_input.command:
node -e '
// Simulate the game step as written, with the cave rebuilt at the host boundaries (ticks every 1/30 s).
const pad = (t) => ({ right: t >= 1/30 && t < 1/4, left:false, up:false, down:false });
const carve = (seed, depth, roughness) => { const rock=Math.round(roughness/10)/10; const start={x:1+(depth%2),y:2}; const exit={x:4+((seed*7+depth*5)%9),y:2}; return {start,exit}; };
let s = { depth: 0, miner: {x:-1,y:-1}, start: [-1,-1] };
let cave = carve(7,0,45);
const r = (n) => Math.round(n*1e6)/1e6;
const pending = [];
for (let k = 1; k <= 15; k++) {
  for (let tick = (k-1)*3+1; tick <= k*3; tick++) {
    const t = r(tick/30);
    if (pending.length && pending[0].at <= t) { cave = carve(7, pending.shift().depth, 45); }
    const [sx, sy] = [cave.start.x, cave.start.y];
    const arrived = sx !== s.start[0] || sy !== s.start[1];
    const at = arrived ? {x:sx,y:sy} : s.miner;
    const dx = pad(t).right ? 1 : 0;
    const miner = {x: at.x+dx, y: at.y};
    const onExit = miner.x===cave.exit.x && miner.y===cave.exit.y;
    s = { depth: onExit ? s.depth+1 : s.depth, miner, start:[sx,sy] };
    if (s.depth !== 0 && tick===9) {}
  }
  const sampled = s.depth;
  if (sampled !== (globalThis.last ?? 0)) { pending.push({at: r((k*3+1)/30), depth: sampled}); globalThis.last = sampled; console.log("sample at", r(k/10), "depth", sampled, "-> cave depth input stamped", r((k*3+1)/30)); }
}
' 2>&1 | head -20
